import {escapeHtml as esc} from './components.js';
import {parseComparisonSymbols,comparePriceSeries,comparisonLabels,safeComparisonUrl} from './comparison-model.js';
const metricLabels={revenue:'매출',operatingIncome:'영업이익',operatingMargin:'영업이익률',operatingCashFlow:'영업현금흐름',freeCashFlow:'잉여현금흐름 (FCF)',eps:'희석 EPS'};
const dimensions={BUSINESS_SEGMENT:'사업부',PRODUCT:'제품',END_MARKET:'적용 산업',DOMESTIC_EXPORT:'수출·내수',GEOGRAPHY:'지역'};
const scopeLabels={CONSOLIDATED:'연결',SEPARATE:'별도',UNKNOWN:'연결·별도 미확인',UNSPECIFIED:'연결·별도 미기재'};
const number=v=>Number.isFinite(v)?v.toLocaleString('ko-KR',{maximumFractionDigits:2}):null;
const amount=v=>typeof v==='string'&&/^[+-]?\d+(?:\.\d+)?$/.test(v)?v.split('.').map((s,i)=>i?s:s.replace(/\B(?=(\d{3})+(?!\d))/g,',')).join('.'):number(v);
const sourceLink=(url,label='원문')=>safeComparisonUrl(url)?`<a href="${esc(safeComparisonUrl(url))}" target="_blank" rel="noopener noreferrer">${esc(label)} ↗</a>`:'';
const colors=['#087f73','#496cb1','#a15b22','#8d52a5'];
export function comparisonSelectionDetail(keys,items=[]){
 return {source:'page',items:parseComparisonSymbols(keys.join(',')).map(key=>{const [market,ticker]=key.split(':'),match=items.find(i=>i.key===key&&i.identity?.key===key&&i.identity?.market===market&&i.identity?.ticker===ticker);return {key,market,ticker,name:String(match?.identity.name||ticker).slice(0,120)};})};
}
export function comparisonSelectionRoute(detail,keys,{interval,period,mode}){
 if(detail?.source!=='tray'||!Array.isArray(detail.items))return null;
 try{const next=parseComparisonSymbols(detail.items.map(i=>i?.key||'INVALID').join(','));if(next.join(',')===keys.join(','))return null;return '/compare?'+new URLSearchParams({symbols:next.join(','),interval,period,mode});}catch{return null;}
}
export function comparisonValuationMarkup(items){
 return `<details class="comparison-stored-ratios"><summary>확보된 추가 재무비율</summary><p class="comparison-note">저장된 원자료의 정의와 기준만 표시합니다. TTM·Forward·EPS·시세 기준이 미확인인 평가 지표는 새로 계산하지 않습니다.</p><div class="comparison-business-grid">${items.map(i=>`<article><h3>${esc(i.identity.name)}</h3>${i.financials?.valuation?.length?i.financials.valuation.map(v=>`<p><strong>${esc(v.label)} ${esc(number(v.value))}${esc(v.unit||'')}</strong></p><p class="comparison-note">${esc(v.basis||'대상기간·기준 미제공')} · ${esc(v.formula||'계산 정의 미제공')}<br>${v.dataAsOf?'자료 기준 '+esc(v.dataAsOf)+' · ':''}저장 조회 ${esc(v.fetchedAt||'미확인')}${/PER|P\/E|주가|평가/i.test(v.label||'')?'<br>시세 기준 '+esc(v.priceAsOf||'미제공'):''}</p>${sourceLink(v.sourceUrl,'비율 근거')}`).join(''):'<p class="comparison-missing">이 종목의 저장된 추가 재무비율이 없습니다.</p>'}</article>`).join('')}</div></details>`;
}
export function comparisonFinancialMarkup(data){
 return `<p class="comparison-note">${esc(data.notice)}</p><table class="comparison-table"><caption>기업별 최근 저장 ${data.interval==='quarter'?'단일 분기':'연간'} 자료 · 원래 단위</caption><thead><tr><th scope="col">지표</th>${data.items.map(i=>`<th scope="col">${esc(i.identity.name)}<small>${esc(i.financials?.period?.label||'기간 미확인')}<br>${esc(i.financials?.period?.end||'')}</small></th>`).join('')}</tr></thead><tbody>${data.metrics.map(m=>`<tr><th scope="row">${esc(metricLabels[m.metricId])}<small>${esc(comparisonLabels[m.status])}</small>${m.reasons.length?`<details><summary>기준 차이</summary>${m.reasons.map(r=>`<p>${esc(r)}</p>`).join('')}</details>`:''}</th>${data.items.map(i=>{const p=i.financials?.observations[m.metricId];return `<td data-company="${esc(i.identity.name)}">${p?`<strong>${esc(number(p.value))} <span>${esc(p.unit)}</span></strong>${Number.isFinite(p.yoy)?`<small>전년 동기 대비 ${p.yoy>0?'+':''}${esc(number(p.yoy))}%</small>`:''}<small>${esc(scopeLabels[p.consolidationScope]||'범위 확인 필요')} · ${p.accountingBasis==='UNKNOWN'?'회계·조정 기준 미확인':esc(p.accountingBasis)}</small><details><summary>값·기간·출처</summary><p>${p.periodStartDerived?'시작일 추정 · ':esc(p.periodStart||'시작일 미확인')+' ~ '}${esc(p.periodEnd)}</p><p>${esc(p.valueOrigin==='DERIVED'?'계산값':'공급원 원자료')} · ${esc(p.formula||p.sourceLocator||'원문 항목 미확인')}</p><p>발표 ${esc(p.sourcePublishedAt||'미제공')}<br>자료 조회 ${esc(p.fetchedAt||'미확인')}</p>${sourceLink(p.sourceUrl,'원본 자료')}</details>`:`<span class="comparison-missing">${esc(i.errors.financials||i.financials?.message||'저장된 값 미확인')}</span>`}</td>`;}).join('')}</tr>`).join('')}</tbody></table>`;
}
export function comparisonBusinessMarkup(item){
 const b=item.business;if(!b)return `<p>${esc(item.errors.business||item.errors.identity||'사업 자료 미확인')}</p>`;
 const available=Object.entries(b.groups||{}).filter(([d,g])=>dimensions[d]&&g.datasets?.length);
 return `${b.descriptions?.[0]?`<p class="comparison-business-summary">${esc(b.descriptions[0].quote.slice(0,260))}</p>${sourceLink(b.descriptions[0].url,'사업 설명 근거')}`:'<p class="comparison-missing">주요 사업 설명 미확인</p>'}${available.slice(0,3).map(([dimension,group])=>{const ds=group.datasets.filter(d=>!d.historical).sort((a,c)=>String(c.period.end).localeCompare(String(a.period.end)))[0]||group.datasets[0];return `<section><h3>${esc(dimensions[dimension])}</h3><p class="comparison-note">${esc(ds.period.label||ds.period.end||'기간 미확인')} · ${esc(scopeLabels[ds.scope]||'범위 미확인')}</p><ul class="comparison-business-values">${ds.items.filter(r=>r.metric!=='NON_DISCLOSURE').slice(0,3).map(r=>`<li><strong>${esc(r.label)}</strong><span>${esc(amount(r.amountExact??r.amount)||'금액 미확인')}${r.unit?' '+esc(r.unit):''}</span><span>${Number.isFinite(r.percent)?esc(number(r.percent))+'%':'비중 미확인'}</span></li>`).join('')}</ul><details><summary>매출 범위·출처</summary><p>${esc(ds.denominator||'분모 미확인')} · ${esc(dimensions[dimension])} 비중이며 다른 항목으로 바꾸거나 100%로 재조정하지 않습니다.</p>${sourceLink(ds.sourceUrl,ds.sourceTitle||'공시 원문')}<p>${esc(ds.items[0]?.locator||'정확한 페이지 미확보 · 원문에서 항목명 검색')}</p></details></section>`;}).join('')||'<p class="comparison-missing">확인된 사업별 매출 표가 없습니다.</p>'}<a data-nav href="/stock/${esc(item.identity.market)}/${encodeURIComponent(item.identity.ticker)}?tab=company">사업·매출 구조 전체 보기 →</a>`;
}
export function comparisonChartMarkup(result,page=0){
 const series=result.series.filter(s=>s.points.length),dates=[...new Set(series.flatMap(s=>s.points.map(p=>p.date)))].sort(),values=series.flatMap(s=>s.points.map(p=>p.value)),low=Math.min(result.mode==='index'?100:0,...values),high=Math.max(result.mode==='index'?100:0,...values),range=high-low||1,pad=range*.12,w=850,h=290,left=65,right=20,top=25,bottom=235,x=d=>left+(w-left-right)*(Date.parse(d)-Date.parse(dates[0]))/(Date.parse(dates.at(-1))-Date.parse(dates[0])||1),y=v=>bottom-(bottom-top)*(v-low+pad)/(range+2*pad),unit=result.mode==='index'?'기준 100':'%';
 const totalPages=Math.ceil(dates.length/50),currentPage=Math.max(0,Math.min(page,totalPages-1)),pointMaps=series.map(s=>new Map(s.points.map(p=>[p.date,p]))),tableDates=dates.slice().reverse().slice(currentPage*50,currentPage*50+50);
 return `${result.baseDate?`<p class="comparison-basis">공통 기준일 <strong>${esc(result.baseDate)}</strong> · ${esc(unit)} · 실제 관측 종가만 사용</p>`:''}${series.length>=2?`<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="공통 거래일 기준 ${result.mode==='index'?'100 지수':'가격수익률'} 비교"><title>공통 기준일 ${esc(result.baseDate)}. 아래 관측값 표에서 정확한 수치를 확인할 수 있습니다.</title>${[low,(low+high)/2,high].map(v=>`<line x1="${left}" x2="${w-right}" y1="${y(v)}" y2="${y(v)}" stroke="var(--line)"/><text x="${left-10}" y="${y(v)+4}" text-anchor="end">${esc(number(v))}</text>`).join('')}${series.map((s,i)=>{const byDate=pointMaps[i],paths=[];let line=[];for(const d of dates){const p=byDate.get(d);if(p)line.push([x(d),y(p.value)].join(','));else if(line.length){paths.push(line);line=[];}}if(line.length)paths.push(line);return paths.map(p=>p.length>1?`<polyline points="${p.join(' ')}" fill="none" stroke="${colors[i]}" stroke-width="2.3" stroke-dasharray="${i===1?'7 3':i===2?'3 2':i===3?'10 3 2 3':'none'}"/>`:`<circle cx="${p[0].split(',')[0]}" cy="${p[0].split(',')[1]}" r="2" fill="${colors[i]}"/>`).join('');}).join('')}<text x="${left}" y="265">${esc(dates[0])}</text><text x="${w-right}" y="265" text-anchor="end">${esc(dates.at(-1))}</text></svg><ul class="comparison-legend">${series.map((s,i)=>`<li><span style="background:${colors[i]}" aria-hidden="true"></span><strong>${esc(s.name||s.key)}</strong> ${esc(number(s.latest?.value))}${result.mode==='index'?'':'%'}<small>${esc(s.currency||'통화 미확인')} · 기준 종가 ${esc(number(s.basePrice))} · ${esc(s.source||'출처 미확인')}<br>마지막 관측 ${esc(s.latest?.date||'미확인')} · 수신 ${esc(s.fetchedAt||'미확인')}</small></li>`).join('')}</ul><details ${page>0?'open':''}><summary>날짜별 실제 관측값</summary><p class="comparison-note">결측 날짜는 값을 만들거나 직전 종가로 채우지 않습니다. 선도 해당 구간에서 끊어 표시합니다.</p><div class="comparison-price-values"><table><thead><tr><th>거래일</th>${series.map(s=>`<th>${esc(s.name||s.key)}</th>`).join('')}</tr></thead><tbody>${tableDates.map(d=>`<tr><th>${d}</th>${pointMaps.map((m,i)=>{const p=m.get(d),s=series[i];return `<td>${p?esc(number(p.price))+' '+esc(s.currency||'')+'<small>'+esc(number(p.value))+(result.mode==='index'?'':'%')+'</small>':'관측 없음'}</td>`;}).join('')}</tr>`).join('')}</tbody></table></div>${totalPages>1?`<p><button data-comparison-price-page="${currentPage-1}" ${currentPage===0?'disabled':''}>최근 관측</button> ${currentPage+1} / ${totalPages} · 50개 날짜씩 <button data-comparison-price-page="${currentPage+1}" ${currentPage+1>=totalPages?'disabled':''}>이전 관측</button></p>`:''}</details>`:'<p class="comparison-missing">함께 비교할 수 있는 시계열이 2개 이상 필요합니다.</p>'}${result.missing.map(m=>`<p class="comparison-missing">${esc(m.key)} · ${esc(m.reason)}</p>`).join('')}<ul class="comparison-note">${result.warnings.map(w=>`<li>${esc(w)}</li>`).join('')}</ul>`;
}
export function mountCompanyCompare(root,{navigate=path=>{location.href=path;}}={}){
 const life=new AbortController();let keys=[];const initial=new URLSearchParams(location.search);try{keys=parseComparisonSymbols(initial.get('symbols'));}catch{}
 let interval=initial.get('interval')==='annual'?'annual':'quarter',period=['1m','3m','6m','1y','3y','all'].includes(initial.get('period'))?initial.get('period'):'1y',mode=initial.get('mode')==='index'?'index':'return',data=null,financialRequest=null,generation=0,priceData=[],priceErrors=[],pricesPending=keys.length,pricePage=0;
 const query=()=>new URLSearchParams({symbols:keys.join(','),interval,period,mode});
 const syncSelection=next=>dispatchEvent(new CustomEvent('moa-compare-selection-change',{detail:comparisonSelectionDetail(next,data?.items||[])}));
 const navigateSelection=next=>{++generation;financialRequest?.abort();syncSelection(next);navigate('/compare?'+new URLSearchParams({symbols:next.join(','),interval,period,mode}));};
 // The page owns the URL selection; the tray owns its session persistence.
 // Only tray-origin events navigate, so mount/name updates cannot feed back.
 addEventListener('moa-compare-selection-change',e=>{const path=comparisonSelectionRoute(e.detail,keys,{interval,period,mode});if(path){++generation;financialRequest?.abort();navigate(path);}},{signal:life.signal});
 syncSelection(keys);
 root.innerHTML=`<div class="page-heading"><div><div class="eyebrow">COMPANY COMPARISON</div><h1>기업 비교</h1><p>사업·실적과 현지 통화 가격 흐름을 2~4개 종목으로 비교합니다.</p></div><a data-nav href="/business">사업으로 기업 찾기 →</a></div><section class="surface comparison-controls"><form><label>시장<select name="market"><option value="KR">국내</option><option value="US">미국</option></select></label><label>종목코드·티커<input name="ticker" maxlength="24" required placeholder="예: 005930 또는 MSFT" aria-label="비교할 종목코드·티커"></label><button>비교에 추가</button></form><div class="comparison-selected">${keys.map(k=>`<button type="button" data-comparison-remove="${esc(k)}" aria-label="${esc(k)} 비교에서 제외">${esc(k)} ×</button>`).join('')}</div><p class="comparison-input-message" role="status"></p></section><section class="surface comparison-prices"><header><h2>가격 흐름</h2><div><label>기간<select data-comparison-period>${[['1m','1개월'],['3m','3개월'],['6m','6개월'],['1y','1년'],['3y','3년'],['all','전체']].map(([v,l])=>`<option value="${v}" ${v===period?'selected':''}>${l}</option>`).join('')}</select></label><label>표시<select data-comparison-mode><option value="return" ${mode==='return'?'selected':''}>등락률 (%)</option><option value="index" ${mode==='index'?'selected':''}>기준 100</option></select></label></div></header><div class="comparison-price-content" aria-live="polite"><p>${keys.length>=2?'과거 시세를 확인하고 있습니다.':'비교할 종목을 2개 이상 선택해 주세요.'}</p></div></section><section class="surface comparison-data"><header><h2>사업·실적</h2><label>실적 기준<select data-comparison-interval><option value="quarter" ${interval==='quarter'?'selected':''}>최근 저장 분기</option><option value="annual" ${interval==='annual'?'selected':''}>최근 저장 연간</option></select></label></header><div class="comparison-results" aria-live="polite"></div></section>`;
 const results=root.querySelector('.comparison-results'),priceRoot=root.querySelector('.comparison-price-content'),message=root.querySelector('.comparison-input-message');
 function renderData(){if(!data)return;results.innerHTML=`<div class="comparison-business-grid">${data.items.map(i=>`<article><header><h2><a data-nav href="/stock/${esc(i.identity.market)}/${encodeURIComponent(i.identity.ticker)}?tab=company">${esc(i.identity.name)}</a></h2><small>${esc(i.identity.market+' · '+i.identity.ticker)} · ${esc(i.identity.exchange||'거래소 미확인')}</small></header>${comparisonBusinessMarkup(i)}<p class="comparison-note">${i.earnings?'저장된 다음 실적일 '+esc(i.earnings.date||i.earnings.publishedAt)+' · '+esc(i.earnings.scheduleStatus||'확정 여부 미확인'):'저장된 다음 실적일 미확인'}</p></article>`).join('')}</div>${comparisonFinancialMarkup(data)}${comparisonValuationMarkup(data.items)}<p class="comparison-note">사업정보는 기업 단위, 시세는 선택한 거래종목 단위입니다. 사업 비중 상승만으로 절대 매출 증가라고 판단하지 않습니다.</p>`;}
 async function loadData(){if(keys.length<2){results.innerHTML='<p>종목을 2개 이상 선택해 주세요.</p>';return;}financialRequest?.abort();financialRequest=new AbortController();const current=++generation,key=new URLSearchParams({symbols:keys.join(','),interval}).toString();results.innerHTML='<p role="status">저장된 기업 자료를 조회하고 있습니다.</p>';
  try{const r=await fetch('/api/compare?'+key,{signal:AbortSignal.any([life.signal,financialRequest.signal])});if(!r.ok)throw Error();const next=await r.json();if(life.signal.aborted||current!==generation||key!==new URLSearchParams({symbols:keys.join(','),interval}).toString())return;if(next.interval!==interval||next.items?.length!==keys.length||next.items.some((item,i)=>item.key!==keys[i]||item.identity?.key!==keys[i]))throw Error('조회 종목이 일치하지 않습니다.');data=next;syncSelection(keys);renderData();}
  catch(error){if(life.signal.aborted||current!==generation||error.name==='AbortError')return;results.innerHTML='<p role="alert">기업 비교 자료 조회 오류</p><button data-comparison-retry>다시 시도</button>';}
 }
 function renderPrices(){if(keys.length<2)return;if(pricesPending){priceRoot.innerHTML='<p role="status">과거 시세 확인 중 · '+(keys.length-pricesPending)+' / '+keys.length+'</p>';return;}const result=comparePriceSeries([...priceData,...priceErrors],{period,mode});priceRoot.innerHTML=comparisonChartMarkup(result,pricePage)+(priceErrors.length?'<button data-comparison-prices-retry>과거 시세 다시 확인</button>':'');}
 async function loadPrice(key){const [market,ticker]=key.split(':');try{const response=await fetch('/api/stock?'+new URLSearchParams({market,id:ticker}),{signal:life.signal});if(!response.ok)throw Error();const feed=await response.json(),s=feed.items?.find(s=>s.market===market&&s.ticker===ticker);if(life.signal.aborted)return;if(!s||!feed.policy?.chart)throw Error();priceData.push({key,market,name:s.name,currency:s.currency,bars:s.history||[],source:s.historySource||feed.source,adjustmentPolicy:s.historyMeta?.adjustment||s.adjustment||'unverified',fetchedAt:s.historyReceivedAt||s.historySyncedAt||null,error:s.historyError});}catch(error){if(life.signal.aborted)return;priceErrors.push({key,market,bars:[],error:error.name==='AbortError'?'조회가 취소되었습니다.':'이 종목의 과거 시세를 불러오지 못했습니다.'});}finally{if(!life.signal.aborted){pricesPending--;renderPrices();}}}
 root.querySelector('form').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target),key=f.get('market')+':'+String(f.get('ticker')).trim().toUpperCase();try{const next=parseComparisonSymbols([...keys,key].join(','));if(next.length===keys.length){message.textContent='이미 비교 중인 종목입니다.';return;}navigateSelection(next);}catch(error){message.textContent=error.message;}},{signal:life.signal});
 root.addEventListener('click',e=>{const b=e.target.closest('[data-comparison-remove]');if(b)navigateSelection(keys.filter(k=>k!==b.dataset.comparisonRemove));if(e.target.closest('[data-comparison-retry]'))void loadData();const page=e.target.closest('[data-comparison-price-page]');if(page){pricePage=Number(page.dataset.comparisonPricePage);renderPrices();}if(e.target.closest('[data-comparison-prices-retry]')){const failed=priceErrors.map(e=>e.key);priceErrors=[];pricesPending=failed.length;renderPrices();for(const k of failed)void loadPrice(k);}},{signal:life.signal});
 root.addEventListener('change',e=>{if(e.target.matches('[data-comparison-interval]')){interval=e.target.value;void loadData();}else if(e.target.matches('[data-comparison-period]')){period=e.target.value;pricePage=0;renderPrices();}else if(e.target.matches('[data-comparison-mode]')){mode=e.target.value;renderPrices();}else return;history.replaceState(history.state,'','/compare?'+query());},{signal:life.signal});
 if(keys.length>=2){void loadData();for(const key of keys)void loadPrice(key);}else results.innerHTML='<p>종목을 2개 이상 선택해 주세요.</p>';
 return {destroy(){++generation;life.abort();financialRequest?.abort();data=null;priceData=[];priceErrors=[];}};
}
